Hub.ApplyPotatoOptimizer = function(self, enabled)
	local lighting = self.Services.Lighting;
	if not self.State.PotatoBackup then
		self.State.PotatoBackup = {};
	end
	if enabled then
		if not self.State.PotatoLightingBackup then
			self.State.PotatoLightingBackup = {GlobalShadows=lighting.GlobalShadows,[LUAOBFUSACTOR_DECRYPT_STR_0("\197\172\117\131\255\66", "\38\131\195\18\198\145")]=lighting.FogEnd,Brightness=lighting.Brightness};
		end
		pcall(function()
			lighting.GlobalShadows = false;
			lighting.FogEnd = 8999999488;
			lighting.Brightness = 2;
		end);
		for _, obj in ipairs(self.Services.Workspace:GetDescendants()) do
			self:OptimizeInstance(obj);
		end
		if not self.State.OptimizerConn then
			self.State.OptimizerConn = self.Services.Workspace.DescendantAdded:Connect(function(obj)
				if self.Config.Toggles.PotatoOptimizer then
					self:OptimizeInstance(obj);
				end
			end);
		end
	else
		if self.State.PotatoLightingBackup then
			pcall(function()
				lighting.GlobalShadows = self.State.PotatoLightingBackup.GlobalShadows;
				lighting.FogEnd = self.State.PotatoLightingBackup.FogEnd;
				lighting.Brightness = self.State.PotatoLightingBackup.Brightness;
			end);
			self.State.PotatoLightingBackup = nil;
		else
			pcall(function()
				lighting.GlobalShadows = self.Config.Toggles.WorldShadows;
				lighting.FogEnd = (self.Config.Toggles.NoFog and 8999999488) or 500;
			end);
		end
		if self.State.OptimizerConn then
			self.State.OptimizerConn:Disconnect();
			self.State.OptimizerConn = nil;
		end
		for obj, data in pairs(self.State.PotatoBackup) do
			if (obj and obj.Parent) then
				pcall(function()
					if (data.Type == "BasePart") then
						obj.Material = data.Material;
						obj.CastShadow = data.CastShadow;
						obj.Reflectance = data.Reflectance;
						if (data.TextureID and obj:IsA("MeshPart")) then
							obj.TextureID = data.TextureID;
						end
					elseif (data.Type == "Decal") then
						obj.Transparency = data.Transparency;
					elseif (data.Type == LUAOBFUSACTOR_DECRYPT_STR_0("\96\198\63\232\49\85\95\251\63\248\48", "\52\51\182\90\139\88")) then
						obj.TextureId = data.TextureId;
					elseif (data.Type == LUAOBFUSACTOR_DECRYPT_STR_0("\194\182\215\224\79\243\184\210\235\70", "\35\150\217\176\135")) then
						obj.Enabled = data.Enabled;
					end
				end);
			end
		end
		table.clear(self.State.PotatoBackup);
	end
end;
Hub.OptimizeInstance = function(self, obj)
	pcall(function()
		if not self.State.PotatoBackup then
			self.State.PotatoBackup = {};
		end
		if obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\219\81\24\9\71\66\100\237", "\22\153\48\107\108\23\35")) then
			local isPlayerChar = obj.Parent and obj.Parent:FindFirstChildOfClass("Humanoid");
			if not isPlayerChar then
				if not self.State.PotatoBackup[obj] then
					self.State.PotatoBackup[obj] = {[LUAOBFUSACTOR_DECRYPT_STR_0("\58\156\171\31", "\137\110\229\219\122\31\21\33")]=LUAOBFUSACTOR_DECRYPT_STR_0("\56\188\43\126\6\74\54\106", "\30\122\221\88\27\86\43\68"),Material=obj.Material,CastShadow=obj.CastShadow,Reflectance=obj.Reflectance,TextureID=((obj:IsA("MeshPart") and obj.TextureID) or nil)};
				end
				obj.Material = Enum.Material.SmoothPlastic;
				obj.CastShadow = false;
				obj.Reflectance = 0;
				if obj:IsA("MeshPart") then
					local nm = obj.Name:lower();
					local pnm = (obj.Parent and obj.Parent.Name:lower()) or "";
					if (nm:find("coin") or pnm:find("coin")) then
