Hub.IsCoinBagFull = function(self)
	local isFull = false;
	local limit = self.Config.Values.AutoFarmBagLimit or 50;
	pcall(function()
		local lp = self.Services.Players.LocalPlayer;
		local pgui = lp:FindFirstChild("PlayerGui");
		local mg = pgui and pgui:FindFirstChild("MainGUI");
		if not mg then
			return;
		end
		local coinBags = mg:FindFirstChild("Game") and mg.Game:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\44\210\25\254\24\200\8\206", "\169\111\189\112\144\90"));
		if not coinBags then
			return;
		end
		local container = coinBags:FindFirstChild("Container");
		if container then
			for _, bagFrame in ipairs(container:GetChildren()) do
				if (bagFrame:IsA("Frame") and bagFrame.Visible) then
					local fullLabel = bagFrame:FindFirstChild("Full");
					if (fullLabel and fullLabel.Visible) then
						isFull = true;
						return;
					end
					for _, lbl in ipairs(bagFrame:GetDescendants()) do
						if (lbl:IsA("TextLabel") and lbl.Visible) then
							local txt = lbl.Text:match("(%d+)");
							if txt then
								local num = tonumber(txt);
								if (num and (num >= limit)) then
									isFull = true;
									return;
								end
							end
						end
					end
				end
			end
		end
		local scriptFolder = coinBags:FindFirstChild("CoinBagContainerScript");
		local fullNotif = scriptFolder and scriptFolder:FindFirstChild("FullBagNotification");
		if (fullNotif and fullNotif.Visible) then
			isFull = true;
			return;
		end
	end);
	return isFull;
end;
Hub.GetAvailableCoins = function(self)
	local list = {};
	local cs = self.Services.CollectionService;
	local ok, tagged = pcall(function()
		return cs:GetTagged(LUAOBFUSACTOR_DECRYPT_STR_0("\238\140\44\163\137\137\26\151\204\143", "\226\173\227\69\205\223\224\105"));
	end);
	if (ok and (type(tagged) == LUAOBFUSACTOR_DECRYPT_STR_0("\76\63\32\87\202", "\123\56\94\66\59\175")) and (#tagged > 0)) then
		for _, v in ipairs(tagged) do
			if (v and v.Parent and v:IsA("BasePart")) then
				if (not v:GetAttribute("Collected") and not v:GetAttribute("Delete")) then
					table.insert(list, v);
				end
			end
		end
	end
	if (#list == 0) then
		local coinContainer = self.Services.Workspace:FindFirstChild("CoinContainer", true);
		if coinContainer then
			for _, c in ipairs(coinContainer:GetChildren()) do
				if (c:IsA("BasePart") and c.Parent and not c:GetAttribute("Collected")) then
					table.insert(list, c);
				elseif (c:IsA("Model") and c.Parent) then
					local p = c.PrimaryPart or c:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\216\66\96\228\42\255\147\238", "\225\154\35\19\129\122\158"));
					if (p and not p:GetAttribute("Collected")) then
						table.insert(list, p);
					end
				end
			end
		end
	end
	return list;
end;
Hub.GetTouchTargets = function(self, coin)
	local list = {};
	local seen = {};
	local function add(p)
		if (p and not seen[p] and p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\120\1\248\82\197\230\194\32", "\84\58\96\139\55\149\135\176")) and p:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\39\48\182\3\70\251\44\18\49\176\13\71\219\42\22\45", "\94\115\95\195\96\46\175"))) then
			seen[p] = true;
			table.insert(list, p);
		end
	end
	add(coin);
	if coin then
		for _, v in ipairs(coin:GetChildren()) do
			add(v);
		end
		local par = coin.Parent;
		if par then
			if par:IsA("BasePart") then
				add(par);
			end
			for _, v in ipairs(par:GetChildren()) do
				add(v);
			end
		end
	end
	if ((#list == 0) and coin) then
		table.insert(list, coin);
	end
	return list;
end;
Hub.FireCoinTouch = function(self, coin)
	if (type(firetouchinterest) ~= "function") then
		return;
	end
	if (not coin or not coin.Parent) then
		return;
	end
	local now = os.clock();
	if ((now - (self.AutoFarm.LastTouch or 0)) < 0.05) then
		return;
	end
	self.AutoFarm.LastTouch = now;
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	if not root then
		return;
	end
	for _, p in ipairs(self:GetTouchTargets(coin)) do
		pcall(firetouchinterest, root, p, 0);
		pcall(firetouchinterest, root, p, 1);
	end
end;
Hub.GetMurdererHRP = function(self)
	local data = self:GetPlayerDataMap();
	if (type(data) == "table") then
		local lp = self.Services.Players.LocalPlayer;
		for name, info in pairs(data) do
			if ((type(info) == "table") and (info.Role == "Murderer") and not info.Dead and (name ~= lp.Name)) then
				local pl = self.Services.Players:FindFirstChild(name);
				local char = pl and pl.Character;
				local root = char and self:GetRoot(char);
				local hum = char and char:FindFirstChildOfClass("Humanoid");
				if (root and (not hum or (hum.Health > 0))) then
					return root;
				end
			end
		end
	end
	for _, plr in ipairs(self.Services.Players:GetPlayers()) do
