	local np = dest;
	if (dist > 0.05) then
		np = root.Position + (dir.Unit * math.min(speed * dt, dist));
	end
	local cf = CFrame.new(np);
	if (mode == "Down") then
		cf = cf * CFrame.Angles(-math.pi * 0.5, 0, 0);
