						if (itemName and (itemName ~= "") and (itemName ~= "Loading...")) then
							local val = self:GetSkinValue(itemName, details);
							self:AttachItemValueBadge(desc, val);
						end
					end
				end
			end
		end
		local old = inv:FindFirstChild("MM2TotalValueHeader", true);
		if old then
			old.Visible = false;
		end
		return;
	end
	if (not weapons or not weapons.Visible) then
		local old = inv:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\211\123\15\47\174\234\87\81\45\160\242\67\88\51\164\255\82\88\9", "\193\158\54\61\123"), true);
		if old then
			old.Visible = false;
		end
		return;
	end
	local itemsFrame = weapons:FindFirstChild("Items");
	if not itemsFrame then
		return;
	end
	local seenSlots = {};
	local totalVal = 0;
	local totalItems = 0;
	for _, desc in ipairs(itemsFrame:GetDescendants()) do
		if ((desc.Name == "NewItem") and not seenSlots[desc]) then
			seenSlots[desc] = true;
			local details = self:GetSlotItemDetails(desc);
			local itemName = (details and details.itemName) or self:GetItemNameFromSlot(desc);
			if (itemName and (itemName ~= "") and (itemName ~= "Loading...")) then
				local amountLbl = desc:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\22\30\46\173\52\24\46\188\39", "\217\85\113\64")) and desc.Container:FindFirstChild("Amount");
