		local txt = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\127\10\212\212\195\131\231\78\3", "\133\43\111\172\160\143\226"));
		txt.Name = "TotalText";
		txt.Size = UDim2.new(1, 0, 1, 0);
		txt.BackgroundTransparency = 1;
		txt.Font = Enum.Font.GothamBold;
		txt.TextColor3 = Color3.fromRGB(255, 215, 80);
		txt.TextSize = 11;
		txt.ZIndex = 10000;
		txt.Parent = header;
	end
	header.Visible = true;
