Hub.ScanMaps = function(self)
	local lobby = self:GetLobby();
	local pads = {"VotePad1","VotePad2",LUAOBFUSACTOR_DECRYPT_STR_0("\203\183\231\118\106\244\249\235", "\149\157\216\147\19\58")};
	local result = {};
	for _, padName in ipairs(pads) do
		local pad = self:GetVotePad(padName);
		local mapName = "";
		local votes = "";
		local imageId = "";
		if pad then
			local vig = pad:FindFirstChild("VoteInfoGui") or pad:FindFirstChildWhichIsA("BillboardGui", true) or pad:FindFirstChildWhichIsA("SurfaceGui", true);
			if vig then
				local mn = vig:FindFirstChild("MapName", true);
				if (mn and mn:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\253\131\0\220\229\135\26\205\197", "\168\169\230\120")) and (mn.Text ~= "")) then
					mapName = mn.Text;
