			local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720);
			local newX = math.clamp(startPos.X.Offset + delta.X, 4, vp.X - 46);
			local newY = math.clamp(startPos.Y.Offset + delta.Y + (startPos.Y.Scale * vp.Y), 30, vp.Y - 50);
