	bar.Parent = row;
	self:Corner(bar, 3);
	local fill = Instance.new("Frame");
	local pct = math.clamp((defaultVal - minVal) / (maxVal - minVal), 0, 1);
	fill.Size = UDim2.new(pct, 0, 1, 0);
	fill.BackgroundColor3 = self.Theme.Accent;
	fill.Parent = bar;
	self:Corner(fill, 3);
